import { posix } from "../deps/std.js";
import { GitLabAPI } from "./apis/gitlab.js";
import { BaseGitAPI, defaultCommitMessage } from "./base-git.js";
export class GitLab extends BaseGitAPI {
    static create(repository, token) {
        const [owner, repo, ...path] = repository.split("/");
        const api = new GitLabAPI("https://gitlab.com", {
            token: token,
            owner: owner,
            repo: repo,
            branch: "main",
            commitMessage: defaultCommitMessage,
        });
        return new GitLab({
            api,
            owner,
            repo,
            path: path.join("/"),
        });
    }
    directory(id) {
        return new GitLab({
            api: this.api,
            owner: this.owner,
            repo: this.repo,
            path: posix.join(this.path, id),
        });
    }
}
export default GitLab;
